module butterworth_filter (  
    input clk,  
    input reset,  
    input [15:0] x, // input signal  
    output reg [15:0] y // output signal  
);  
    reg [15:0] y1, y2; // previous outputs  
    reg [15:0] a0, a1, a2; // filter coefficients  
    reg [15:0] b1, b2; // feedback coefficients  

    initial begin  
        // Initialize coefficients for Butterworth filter  
        a0 = 16'h1E38; // Example coefficient  
        a1 = 16'h1E38; // Example coefficient  
        a2 = 16'h1E38; // Example coefficient  
        b1 = 16'h02A5; // Example coefficient  
        b2 = 16'h01C7; // Example coefficient  
    end  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            y <= 0;  
            y1 <= 0;  
            y2 <= 0;  
        end else begin  
            y <= (a0 * x + a1 * y1 + a2 * y2) >> 16; // shift for fixed point  
            // Update previous outputs  
            y2 <= y1;  
            y1 <= y;  
        end  
    end  
endmodule

