module phase_detector (  
    input clk_a,  
    input clk_b,  
    output reg [1:0] phase_out  
);  
    reg clk_a_prev, clk_b_prev;  

    always @(posedge clk_a or posedge clk_b) begin  
        clk_a_prev <= clk_a;  
        clk_b_prev <= clk_b;  

        if (clk_a_prev && !clk_a && !clk_b_prev && clk_b)  
            phase_out <= 2'b01; // clk_a is leading  
        else if (!clk_a_prev && clk_a && clk_b_prev && !clk_b)  
            phase_out <= 2'b10; // clk_a is lagging  
        else  
            phase_out <= 2'b00; // in phase  
    end  
endmodule

