module NoiseSuppression (  
    input wire clk,  
    input wire rst,  
    input wire noisy_signal,  
    output reg clean_signal  
);  
    // State variable to hold the last clean signal  
    reg last_clean_signal;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            last_clean_signal <= 1'b0;  
            clean_signal <= 1'b0;  
        end else begin  
            // Simple noise suppression logic  
            if (noisy_signal) begin  
                clean_signal <= last_clean_signal;  // Maintain last clean signal  
            end else begin  
                clean_signal <= noisy_signal;  // Accept new clean signal  
            end  
            last_clean_signal <= clean_signal;  // Update last clean signal  
        end  
    end  
endmodule

