module spi_controller (  
    input wire clk,  
    input wire rst,  
    input wire mosi,  
    output reg miso,  
    output reg cs,  
    input wire start,  
    input wire [7:0] data_in  
);  
    reg [2:0] state;  
    reg [2:0] bit_count;  
    reg [7:0] shift_reg;  

    parameter IDLE = 3'b000,  
              SEND = 3'b001,  
              RECEIVE = 3'b010;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= IDLE;  
            cs <= 1'b1;  
            miso <= 1'b0;  
            bit_count <= 3'b000;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (start) begin  
                        cs <= 1'b0;  
                        shift_reg <= data_in;  
                        bit_count <= 3'b000;  
                        state <= SEND;  
                    end  
                end  
                SEND: begin  
                    if (bit_count < 3'b100) begin  
                        miso <= shift_reg[7];  
                        shift_reg <= {shift_reg[6:0], 1'b0};  
                        bit_count <= bit_count + 1;  
                    end else begin  
                        cs <= 1'b1;  
                        state <= RECEIVE;  
                    end  
                end  
                RECEIVE: begin  
                    if (bit_count < 3'b100) begin  
                        bit_count <= bit_count + 1;  
                        // Here you would typically receive data on a separate input signal  
                    end else begin  
                        state <= IDLE;  
                    end  
                end  
            endcase  
        end  
    end  
endmodule

