module CurrentSensor (  
    input wire clk,  
    input wire reset,  
    input wire [7:0] current_level,  
    output reg warning_signal  
);  
    parameter THRESHOLD = 8'd100;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            warning_signal <= 1'b0;  
        end else begin  
            if (current_level > THRESHOLD) begin  
                warning_signal <= 1'b1;  
            end else begin  
                warning_signal <= 1'b0;  
            end  
        end  
    end  
endmodule

