`timescale 1ns/1ps

module stop_and_wait_tb;

    // Testbench signals (sequential circuit)
    reg ack;
    reg clk;
    reg rst;
    reg start_send;
    wire [7:0] data_out;
    wire done;
    wire send;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    stop_and_wait dut (
        .ack(ack),
        .clk(clk),
        .rst(rst),
        .start_send(start_send),
        .data_out(data_out),
        .done(done),
        .send(send)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            rst = 1;
            start_send = 0;
            ack = 0;
            #10;
            @(posedge clk);
            rst = 0;
            @(posedge clk);
            #2;
        end
        endtask
    task testcase001;

        begin
            test_num = 1;
            $display("Testcase %0d: Idle State Check", test_num);
            reset_dut();


            repeat(5) @(posedge clk);


            #1;



            check_outputs(8'h00, 1'b0, 1'b0);
        end
        endtask

    task testcase002;

        integer i;
        begin
            test_num = 2;
            $display("Testcase %0d: Full 8-bit Transmission", test_num);
            reset_dut();


            @(posedge clk);
            start_send = 1;
            @(posedge clk);
            start_send = 0;


            for (i = 0; i < 8; i = i + 1) begin

                wait(send === 1'b1);
                @(posedge clk);
                #1 ack = 1;


                wait(send === 1'b0);
                @(posedge clk);
                #1 ack = 0;
            end


            wait(done === 1'b1);
            @(posedge clk);



            #1;




            check_outputs(data_out, 1'b1, 1'b0);
        end
        endtask

    task testcase003;

        begin
            test_num = 3;
            $display("Testcase %0d: Protocol Halt Without ACK", test_num);
            reset_dut();


            @(posedge clk);
            start_send = 1;
            @(posedge clk);
            start_send = 0;


            wait(send === 1'b1);


            repeat(20) @(posedge clk);



            #1;




            check_outputs(data_out, 1'b0, 1'b1);
        end
        endtask

    task testcase004;

        integer i, j;
        begin
            test_num = 4;
            $display("Testcase %0d: Consecutive Transmissions", test_num);
            reset_dut();


            for (j = 0; j < 2; j = j + 1) begin
                @(posedge clk);
                start_send = 1;
                @(posedge clk);
                start_send = 0;

                for (i = 0; i < 8; i = i + 1) begin
                    wait(send === 1'b1);
                    @(posedge clk);
                    #1 ack = 1;
                    wait(send === 1'b0);
                    @(posedge clk);
                    #1 ack = 0;
                end
                wait(done === 1'b1);
                @(posedge clk);
            end


            #1;



            check_outputs(data_out, 1'b1, 1'b0);
        end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("stop_and_wait Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input [7:0] expected_data_out;
        input expected_done;
        input expected_send;
        begin
            if (expected_data_out === (expected_data_out ^ data_out ^ expected_data_out) &&
                expected_done === (expected_done ^ done ^ expected_done) &&
                expected_send === (expected_send ^ send ^ expected_send)) begin
                $display("PASS");
                $display("  Outputs: data_out=%h, done=%b, send=%b",
                         data_out, done, send);
                pass_count = pass_count + 1;
            end else begin
                $display("FAIL");
                $display("  Expected: data_out=%h, done=%b, send=%b",
                         expected_data_out, expected_done, expected_send);
                $display("  Got:      data_out=%h, done=%b, send=%b",
                         data_out, done, send);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

    // Optional: Waveform dump for debugging
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0,ack, clk, rst, start_send, data_out, done, send);
    end

endmodule

