    always @(posedge clk or posedge reset) begin
        if (reset) begin
            spi_clk <= 0;
            spi_mosi <= 0;
            data_out <= 0;
            done <= 0;
            bit_counter <= 0;
            shift_reg <= 0;
        end else begin
            if (start && bit_counter == 0) begin
                shift_reg <= data_in; 
                bit_counter <= 8; 
                done <= 0;
            end

            if (bit_counter > 0) begin
                spi_clk <= ~spi_clk; 
                if (spi_clk) begin
                    spi_mosi <= shift_reg[7]; 
                    shift_reg <= {shift_reg[6:0], 1'b0}; 
                end else begin
                    data_out <= {data_out[6:0], spi_miso}; 
                    bit_counter <= bit_counter - 1; 
                end
            end else if (bit_counter == 0 && !done) begin
                done <= 1; 
                spi_clk <= 0; 
                spi_mosi <= 0; 
            end
        end
    end
endmodule

