module rsa_encrypt (  
    input clk,  
    input rst,  
    input [15:0] plaintext,  
    input [15:0] n,  
    input [15:0] e,  
    output reg [15:0] ciphertext  
);  

    reg [31:0] temp;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            ciphertext <= 16'b0;  
        end else begin  
            temp <= plaintext;  
            ciphertext <= (temp ** e) % n;  
        end  
    end  
endmodule

