module temp_shutdown(  
    input wire [7:0] temperature,  
    input wire clk,  
    input wire rst,  
    output reg shutdown  
);  
    parameter THRESHOLD = 8'd75;  
    parameter HOLD_TIME = 8'd5;  
    reg [3:0] counter;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            shutdown <= 1'b0;  
            counter <= 4'd0;  
        end else if (temperature > THRESHOLD) begin  
            if (counter < HOLD_TIME)  
                counter <= counter + 1;  
            if (counter == HOLD_TIME)  
                shutdown <= 1'b1;  
        end else begin  
            counter <= 4'd0;  
            shutdown <= 1'b0;  
        end  
    end  
endmodule

