module bst(clk, reset, value, op, found, bst_root);  
    input clk;  
    input reset;  
    input [7:0] value;  
    input op; // 0 for insert, 1 for search  
    output reg found;  
    output reg [7:0] bst_root; // root of the BST  

    reg [7:0] left_child;  
    reg [7:0] right_child;  
    reg [1:0] state; // 0: idle, 1: inserting, 2: searching  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            bst_root <= 8'b0;  
            left_child <= 8'b0;  
            right_child <= 8'b0;  
            found <= 0;  
            state <= 0;  
        end else begin  
            case (state)  
                0: begin  
                    if (op == 0) begin // Insert operation  
                        state <= 1;  
                    end else if (op == 1) begin // Search operation  
                        state <= 2;  
                    end  
                end  
                1: begin // Inserting value  
                    if (bst_root == 8'b0) begin  
                        bst_root <= value;  
                    end else if (value < bst_root) begin  
                        left_child <= value;  
                    end else begin  
                        right_child <= value;  
                    end  
                    state <= 0;  
                end  
                2: begin // Searching value  
                    if (bst_root == value) begin  
                        found <= 1;  
                    end else if (value < bst_root) begin  
                        if (left_child == 8'b0)  
                            found <= 0;  
                        else  
                            found <= 1; // Simplified for the example  
                    end else begin  
                        if (right_child == 8'b0)  
                            found <= 0;  
                        else  
                            found <= 1; // Simplified for the example  
                    end  
                    state <= 0;  
                end  
            endcase  
        end  
    end  
endmodule

