module CSPRNG (  
    input clk,  
    input reset,  
    output reg [4:0] random_number  
);  
    reg [4:0] lfsr;  

    always @(posedge clk or posedge reset) begin  
        if (reset)  
            lfsr <= 5'b00001; // Seed value  
        else begin  
            lfsr[0] <= lfsr[4] ^ lfsr[3]; // Feedback polynomial x^5 + x^3 + 1  
            lfsr[4:1] <= lfsr[3:0];  
        end  
    end  

    always @(posedge clk)  
        random_number <= lfsr;  
endmodule

