module PLL_4x (
    input wire clk_ref,
    input wire reset,
    output reg clk_out
);
    reg [1:0] counter;

    always @(posedge clk_ref or posedge reset) begin
        if (reset) begin
            clk_out <= 0;
            counter <= 0;
        end else begin
            if (counter == 3) begin
                clk_out <= ~clk_out; // Toggle output clock on every 4th reference clock
                counter <= 0;
            end else begin
                counter <= counter + 1;
            end
        end
    end
endmodule

