module divide_by_8_counter (  
    input clk,  
    input reset,  
    output reg divided_clk  
);  
    reg [2:0] count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            count <= 3'b000;  
            divided_clk <= 0;  
        end else begin  
            if (count == 3'b111) begin  
                count <= 3'b000;  
                divided_clk <= ~divided_clk;  
            end else begin  
                count <= count + 1;  
            end  
        end  
    end  
endmodule

