module zero_crossing_detector (
    input wire clk,
    input wire rst,
    input wire signal_in,
    output reg zero_cross
);
    reg signal_prev;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            zero_cross <= 0;
            signal_prev <= 0;
        end else begin
            zero_cross <= (signal_in && !signal_prev) || (!signal_in && signal_prev);
            signal_prev <= signal_in;
        end
    end
endmodule

