module divide_by_2 (  
    input clk,  
    input rst_n,  
    input [0:0] in,  
    output reg [0:0] out  
);  
    always @(posedge clk or negedge rst_n) begin  
        if (!rst_n)  
            out <= 1'b0;  
        else  
            out <= in >> 1;  
    end  
endmodule

module counter_64bit (
    input wire clk,
    input wire reset,
    output reg [63:0] count
);

always @(posedge clk or posedge reset) begin
    if (reset) begin
        count <= 64'b0;
    end else begin
        count <= count + 1;
    end
end

endmodule

