module dma_controller (  
    input clk,  
    input rst,  
    input req_a,  
    input req_b,  
    output reg grant_a,  
    output reg grant_b,  
    output reg busy  
);  
    reg [1:0] state;  
    parameter IDLE = 2'b00, GRANT_A = 2'b01, GRANT_B = 2'b10;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= IDLE;  
            grant_a <= 0;  
            grant_b <= 0;  
            busy <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (req_a) begin  
                        grant_a <= 1;  
                        grant_b <= 0;  
                        busy <= 1;  
                        state <= GRANT_A;  
                    end else if (req_b) begin  
                        grant_a <= 0;  
                        grant_b <= 1;  
                        busy <= 1;  
                        state <= GRANT_B;  
                    end  
                end  
                GRANT_A: begin  
                    // Simulate transfer time  
                    grant_a <= 1;  
                    if (!req_a) begin  
                        busy <= 0;  
                        state <= IDLE;  
                    end  
                end  
                GRANT_B: begin  
                    // Simulate transfer time  
                    grant_b <= 1;  
                    if (!req_b) begin  
                        busy <= 0;  
                        state <= IDLE;  
                    end  
                end  
            endcase  
        end  
    end  
endmodule

module watchdog_timer(  
    input clk,  
    input rst,  
    input [3:0] timeout_value,  
    output reg timed_out  
);  
    reg [3:0] counter;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            counter <= 0;  
            timed_out <= 0;  
        end else begin  
            if (counter < timeout_value) begin  
                counter <= counter + 1;  
                timed_out <= 0;  
            end else begin  
                timed_out <= 1;  
            end  
        end  
    end  
endmodule

