module dvfs_controller (
    input wire clk,
    input wire [1:0] workload,
    output reg [1:0] voltage,
    output reg [1:0] frequency
);

    always @(posedge clk) begin
        case (workload)
            2'b00: begin
                voltage <= 2'b00; 
                frequency <= 2'b00; 
            end
            2'b01: begin
                voltage <= 2'b01; 
                frequency <= 2'b01; 
            end
            2'b10: begin
                voltage <= 2'b10; 
                frequency <= 2'b10; 
            end
            2'b11: begin
                voltage <= 2'b11; 
                frequency <= 2'b11; 
            end
            default: begin
                voltage <= 2'b00; 
                frequency <= 2'b00; 
            end
        endcase
    end
endmodule

module restoring_divider (  
    input clk,  
    input reset,  
    input [3:0] dividend,  
    input [3:0] divisor,  
    output reg [3:0] quotient,  
    output reg [3:0] remainder,  
    output reg done  
);  

    reg [3:0] temp_dividend;  
    reg [3:0] temp_divisor;  
    reg [3:0] temp_quotient;  
    reg [2:0] count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            temp_dividend <= 0;  
            temp_divisor <= 0;  
            temp_quotient <= 0;  
            count <= 0;  
            done <= 0;  
            quotient <= 0;  
            remainder <= 0;  
        end else begin  
            if (count == 0) begin  
                temp_dividend <= dividend;  
                temp_divisor <= divisor;  
                temp_quotient <= 0;  
                count <= 4;  
                done <= 0;  
            end else if (count > 0) begin  
                temp_quotient <= {temp_quotient[2:0], 1'b0};  
                temp_dividend <= {temp_dividend[3:0], 1'b0};  
                temp_dividend <= temp_dividend - temp_divisor;  
                if (temp_dividend[3] == 1) begin  
                    temp_dividend <= temp_dividend + temp_divisor;  
                end else begin  
                    temp_quotient[0] <= 1;  
                end  
                count <= count - 1;  
            end else begin  
                quotient <= temp_quotient;  
                remainder <= temp_dividend;  
                done <= 1;  
            end  
        end  
    end  
endmodule

