module adaptive_lms_filter (
    input clk,
    input reset,
    input signed [15:0] x, // input sample
    input signed [15:0] d, // desired output sample
    output reg signed [15:0] y // filtered output
);
    parameter N = 5; // Number of taps
    parameter signed [15:0] mu = 16'h0001; // Step size
    reg signed [15:0] w [0:N-1]; // Weights
    reg signed [15:0] x_delayed [0:N-1]; // Delayed input samples
    integer i;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Initialize weights and output
            for (i = 0; i < N; i = i + 1) begin
                w[i] <= 16'h0000;
                x_delayed[i] <= 16'h0000;
            end
            y <= 16'h0000;
        end else begin
            // Shift input samples
            for (i = N-1; i > 0; i = i - 1) begin
                x_delayed[i] <= x_delayed[i-1];
            end
            x_delayed[0] <= x;

            // Compute output
            y <= 16'h0000;
            for (i = 0; i < N; i = i + 1) begin
                y <= y + (w[i] * x_delayed[i]);
            end

            // Update weights
            for (i = 0; i < N; i = i + 1) begin
                w[i] <= w[i] + (mu * (d - y) * x_delayed[i]);
            end
        end
    end
endmodule

