module dma_controller (
    input clk,
    input reset,
    input channel_select,
    input start,
    input [4:0] source_addr,
    input [4:0] dest_addr,
    input [7:0] data_in,
    output reg [7:0] data_out,
    output reg done
);
    reg [4:0] current_source;
    reg [4:0] current_dest;
    reg [7:0] memory [31:0]; // Simple memory for simulation
    reg transferring;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            done <= 0;
            transferring <= 0;
        end else if (start && !transferring) begin
            current_source <= source_addr;
            current_dest <= dest_addr;
            transferring <= 1;
            done <= 0;
        end else if (transferring) begin
            data_out <= memory[current_source]; // Read from source
            memory[current_dest] <= data_out;   // Write to destination
            current_source <= current_source + 1; // Move to next source
            current_dest <= current_dest + 1;     // Move to next destination

            // End transfer conditions
            if (current_source == source_addr + 1 || current_dest == dest_addr + 1) begin
                transferring <= 0;
                done <= 1;
            end
        end
    end
endmodule

