module rs_encoder(
    input wire clk,
    input wire rst,
    input wire [3:0] data_in,
    output reg [6:0] codeword_out,
    output reg valid
);
    reg [2:0] state;
    reg [3:0] generator_poly;

    parameter IDLE = 3'b000, READ = 3'b001, ENCODE = 3'b010, OUTPUT = 3'b011;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            codeword_out <= 7'b0;
            valid <= 0;
            generator_poly <= 4'b1011; // Example generator polynomial
        end else begin
            case (state)
                IDLE: begin
                    if (valid) state <= READ;
                end
                READ: begin
                    // Read input data
                    state <= ENCODE;
                end
                ENCODE: begin
                    // Perform encoding (simple example)
                    codeword_out <= {data_in, 3'b0} ^ generator_poly; // XOR with generator
                    state <= OUTPUT;
                end
                OUTPUT: begin
                    valid <= 1;
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

