module iir_filter (
    input clk,
    input rst,
    input [15:0] input_sample,
    output reg [15:0] output_sample
);
    reg [15:0] prev_output;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            prev_output <= 16'b0;
            output_sample <= 16'b0;
        end else begin
            // Apply the IIR filter equation
            output_sample <= input_sample + (prev_output >> 1); // 0.5 * prev_output
            prev_output <= output_sample;
        end
    end
endmodule

