module DFS (
    input wire clk,
    input wire reset,
    input wire start,
    output reg [3:0] current_node,
    output reg done
);
    reg [3:0] stack [0:15]; // Stack for DFS
    reg [3:0] top; // Stack pointer
    reg [15:0] visited; // Visited nodes
    reg [3:0] adjacency_matrix [0:15][0:15]; // Adjacency matrix
    integer i;

    initial begin
        // Example adjacency matrix for a simple graph
        //   0 -- 1
        //   |    |
        //   2 -- 3
        adjacency_matrix[0][1] = 1;
        adjacency_matrix[1][0] = 1;
        adjacency_matrix[0][2] = 1;
        adjacency_matrix[2][0] = 1;
        adjacency_matrix[1][3] = 1;
        adjacency_matrix[3][1] = 1;
        adjacency_matrix[2][3] = 1;
        adjacency_matrix[3][2] = 1;

        // Initialize
        current_node = 4'b0000;
        done = 0;
        top = 0;
        visited = 0;
    end

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_node <= 4'b0000;
            done <= 0;
            top <= 0;
            visited <= 0;
        end else if (start) begin
            if (top == 0) begin
                stack[top] <= 4'b0000; // Start from node 0
                visited[0] <= 1;
                top <= top + 1;
            end

            if (top > 0) begin
                top <= top - 1; // Pop from stack
                current_node <= stack[top];

                // Check for unvisited neighbors
                for (i = 0; i < 16; i = i + 1) begin
                    if (adjacency_matrix[current_node][i] && !visited[i]) begin
                        stack[top] <= i; // Push neighbor onto stack
                        visited[i] <= 1; // Mark as visited
                        top <= top + 1;
                    end
                end
            end

            if (top == 0) begin
                done <= 1; // DFS complete
            end
        end
    end
endmodule

