module i2c_controller(  
    input wire clk,  
    input wire reset,  
    input wire start,  
    input wire [7:0] data,  
    input wire stop,  
    output reg sda,  
    output reg scl,  
    output reg busy  
);  
    reg [3:0] state;  
    reg [2:0] bit_index;  

    parameter IDLE = 4'b0000;  
    parameter START = 4'b0001;  
    parameter SEND_DATA = 4'b0010;  
    parameter STOP = 4'b0011;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            sda <= 1;  
            scl <= 0;  
            busy <= 0;  
            bit_index <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    busy <= 0;  
                    if (start) begin  
                        state <= START;  
                    end  
                end  
                START: begin  
                    sda <= 0;  
                    scl <= 0;  
                    busy <= 1;  
                    state <= SEND_DATA;  
                end  
                SEND_DATA: begin  
                    if (bit_index < 8) begin  
                        sda <= data[7 - bit_index];  
                        scl <= 1;  
                        bit_index <= bit_index + 1;  
                        #1 scl <= 0;  
                    end else begin  
                        state <= STOP;  
                    end  
                end  
                STOP: begin  
                    sda <= 1;  
                    scl <= 1;  
                    busy <= 0;  
                    state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

module restoring_divider(
    input clk,
    input start,
    input [3:0] dividend,
    input [3:0] divisor,
    output reg [3:0] quotient,
    output reg [3:0] remainder,
    output reg done
);
    reg [3:0] temp_dividend;
    reg [3:0] temp_remainder;
    reg [2:0] count; // to count clock cycles

    always @(posedge clk or posedge start) begin
        if (start) begin
            quotient <= 4'b0000;
            remainder <= 4'b0000;
            temp_dividend <= dividend;
            temp_remainder <= 4'b0000;
            count <= 3'b100; // Start with 4 bits
            done <= 0;
        end else if (count > 0) begin
            temp_remainder <= {temp_remainder[2:0], temp_dividend[3]};
            temp_dividend <= {temp_dividend[2:0], 1'b0};
            if (temp_remainder >= divisor) begin
                temp_remainder <= temp_remainder - divisor;
                quotient <= {quotient[2:0], 1'b1};
            end else begin
                quotient <= {quotient[2:0], 1'b0};
            end
            count <= count - 1;
        end else begin
            remainder <= temp_remainder;
            done <= 1;
        end
    end
endmodule

