module pipeline_processor (  
    input clk,  
    input reset,  
    input [3:0] instruction, // 4-bit instruction, where 0001 = ADD, 0010 = SUB  
    output reg [7:0] result // 8-bit result  
);  
    reg [3:0] IF_ID_instruction;  
    reg [3:0] ID_EX_instruction;  
    reg [7:0] ID_EX_operandA, ID_EX_operandB;  
    reg [7:0] EX_MEM_result;  
    reg [7:0] MEM_WB_result;  
    reg stall;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            IF_ID_instruction <= 0;  
            ID_EX_instruction <= 0;  
            ID_EX_operandA <= 0;  
            ID_EX_operandB <= 0;  
            EX_MEM_result <= 0;  
            MEM_WB_result <= 0;  
            result <= 0;  
            stall <= 0;  
        end else begin  
            // Stage IF  
            IF_ID_instruction <= instruction;  
            // Stage ID  
            ID_EX_instruction <= IF_ID_instruction;  
            ID_EX_operandA <= 8'd5; // Sample operand A  
            ID_EX_operandB <= 8'd3; // Sample operand B  
            // Stage EX  
            case (ID_EX_instruction)  
                4'b0001: EX_MEM_result <= ID_EX_operandA + ID_EX_operandB; // ADD  
                4'b0010: EX_MEM_result <= ID_EX_operandA - ID_EX_operandB; // SUB  
                default: EX_MEM_result <= 0;  
            endcase  
            // Stage MEM  
            MEM_WB_result <= EX_MEM_result;  
            // Stage WB  
            result <= MEM_WB_result;  
        end  
    end  
endmodule

